from astro_pi_replay.libcamera.libcamera._libcamera.stream import StreamFormats


def test_StreamFormats_range():
    """
    Checks StreamFormats.range function's output matches
    real for picamera2's default main stream still config
    (generated using cam.create_still_configuration())
    """

    sf = StreamFormats({
    })

    expected = """\
[(libcamera.PixelFormat('NV21'), libcamera.SizeRange((64, 64), (4056, 3040), 2, 2)), (libcamera.PixelFormat('YUV420'), libcamera.SizeRange((64, 64), (4056, 3040), 2, 2)), (libcamera.PixelFormat('NV12'), libcamera.SizeRange((64, 64), (4056, 3040), 2, 2)), (libcamera.PixelFormat('YVU420'), libcamera.SizeRange((64, 64), (4056, 3040), 2, 2)), (libcamera.PixelFormat('XBGR8888'), libcamera.SizeRange((64, 64), (4056, 3040), 1, 1)), (libcamera.PixelFormat('BGR888'), libcamera.SizeRange((64, 64), (4056, 3040), 1, 1)), (libcamera.PixelFormat('RGB888'), libcamera.SizeRange((64, 64), (4056, 3040), 1, 1)), (libcamera.PixelFormat('XRGB8888'), libcamera.SizeRange((64, 64), (4056, 3040), 1, 1)), (libcamera.PixelFormat('RGB565'), libcamera.SizeRange((64, 64), (4056, 3040), 1, 1)), (libcamera.PixelFormat('YVYU'), libcamera.SizeRange((64, 64), (4056, 3040), 2, 2)), (libcamera.PixelFormat('YUYV'), libcamera.SizeRange((64, 64), (4056, 3040), 2, 2)), (libcamera.PixelFormat('VYUY'), libcamera.SizeRange((64, 64), (4056, 3040), 2, 2)), (libcamera.PixelFormat('UYVY'), libcamera.SizeRange((64, 64), (4056, 3040), 2, 2))]"""

    actual = repr([(pix, sf.range(pix)) for pix in sf.pixel_formats])
    assert actual == expected


